import { useEffect, useState } from 'react'
import { useApp } from '../state/AppContext'
import { api } from '../state/api'
import { Badge, Button, Card, CardHeader, InfoNote, Modal } from './ui'

// Administrator-only: create operator accounts for booth helpers, reset a forgotten password
// or switch an account off. Every change is audited. Passwords are generated by the server
// and shown once; administrator accounts are managed on the laptop, not here.
export default function StaffAccounts() {
  const { admin, notify } = useApp()
  const [staff, setStaff] = useState([])
  const [username, setUsername] = useState('')
  const [error, setError] = useState('')
  const [working, setWorking] = useState(false)
  const [issued, setIssued] = useState(null) // { username, password, created }

  useEffect(() => {
    let current = true
    api('/admin/staff')
      .then((data) => current && setStaff(data.staff))
      .catch((failure) => current && setError(failure.message))
    return () => {
      current = false
    }
  }, [])

  function replace(account) {
    setStaff((list) =>
      list.some((s) => s.id === account.id)
        ? list.map((s) => (s.id === account.id ? account : s))
        : [...list, account],
    )
  }

  async function run(request) {
    setWorking(true)
    setError('')
    try {
      return await request()
    } catch (failure) {
      setError(failure.message)
      return null
    } finally {
      setWorking(false)
    }
  }

  async function add(event) {
    event.preventDefault()
    const data = await run(() =>
      api('/admin/staff', {
        method: 'POST',
        csrf: admin.csrf,
        body: { username: username.trim() },
      }),
    )
    if (!data) return
    replace(data.staff)
    setUsername('')
    setIssued({ username: data.staff.username, password: data.password, created: true })
  }

  async function reset(account) {
    const data = await run(() =>
      api(`/admin/staff/${account.id}/password`, { method: 'POST', csrf: admin.csrf }),
    )
    if (!data) return
    setIssued({ username: account.username, password: data.password, created: false })
  }

  async function toggle(account) {
    const data = await run(() =>
      api(`/admin/staff/${account.id}/enabled`, {
        method: 'POST',
        csrf: admin.csrf,
        body: { enabled: !account.enabled },
      }),
    )
    if (!data) return
    replace(data.staff)
    notify(
      data.staff.enabled
        ? `${account.username} can sign in again.`
        : `${account.username} is switched off and signed out.`,
    )
  }

  return (
    <Card>
      <CardHeader
        title="Staff accounts"
        subtitle="Operators run the line: queue, no-shows, re-entry QR and holding a round for review."
      />
      <p className="tw:text-muted tw:text-[13px] tw:leading-[1.7] tw:my-4">
        Only administrators can void or recover a round&apos;s score, train Stack Intelligence, use
        the simulator or manage accounts.
      </p>
      <form className="tw:mt-3 tw:flex tw:flex-wrap tw:items-end tw:gap-2.5" onSubmit={add}>
        <label className="tw:grid tw:gap-2 tw:text-muted tw:text-[13px] tw:[&_select]:p-3 tw:[&_select]:rounded-xl tw:[&_select]:border tw:[&_select]:border-solid tw:[&_select]:border-line tw:[&_select]:bg-surface tw:[&_select]:text-ink tw:min-w-0 tw:flex-1">
          New operator username
          <input
            className="text-input"
            value={username}
            maxLength={40}
            autoComplete="off"
            placeholder="e.g. booth-1"
            onChange={(event) => setUsername(event.target.value)}
          />
        </label>
        <Button type="submit" disabled={working || username.trim().length < 3}>
          Add operator
        </Button>
      </form>
      {error && (
        <p className="field-error" role="alert">
          {error}
        </p>
      )}
      <ul
        className="tw:m-0 tw:mt-4 tw:flex tw:list-none tw:flex-col tw:gap-2 tw:p-0"
        aria-label="Staff accounts"
      >
        {staff.map((account) => (
          <li
            key={account.id}
            className="tw:flex tw:flex-wrap tw:items-center tw:justify-between tw:gap-2.5"
          >
            <span className="tw:flex tw:min-w-0 tw:items-center tw:gap-2">
              <strong className="tw:truncate">{account.username}</strong>
              <Badge tone="soft">{account.role === 'admin' ? 'Administrator' : 'Operator'}</Badge>
              {!account.enabled && <Badge>Switched off</Badge>}
            </span>
            {account.role === 'operator' && (
              <span className="tw:flex tw:gap-2">
                <Button
                  tone="light"
                  disabled={working}
                  onClick={() => void reset(account)}
                  aria-label={`Reset password for ${account.username}`}
                >
                  Reset password
                </Button>
                <Button
                  tone="light"
                  disabled={working}
                  onClick={() => void toggle(account)}
                  aria-label={`${account.enabled ? 'Switch off' : 'Switch on'} ${account.username}`}
                >
                  {account.enabled ? 'Switch off' : 'Switch on'}
                </Button>
              </span>
            )}
          </li>
        ))}
      </ul>
      <Modal
        title={issued ? `Password for ${issued.username}` : 'Password'}
        description={
          issued?.created
            ? 'The operator account is ready. Give this password to the operator in person.'
            : 'The old password no longer works and the operator was signed out.'
        }
        open={Boolean(issued)}
        onOpenChange={(open) => {
          if (!open) setIssued(null)
        }}
      >
        {issued && (
          <>
            <p className="tw:my-4 tw:text-center tw:font-mono tw:text-2xl tw:font-bold tw:tracking-wide">
              {issued.password}
            </p>
            <InfoNote>
              It is shown only this once. If it is lost, reset it again. Do not send it in a group
              chat.
            </InfoNote>
            <div className="modal-actions">
              <Button onClick={() => setIssued(null)}>Done</Button>
            </div>
          </>
        )}
      </Modal>
    </Card>
  )
}
